/**
 * Generates docs/api.md (IPC channel reference) from channels.ts + handler registrations.
 *
 * Run: npm run docs:api
 * Do not edit docs/api.md by hand — regenerate after IPC changes.
 *
 * Manual narrative lives in docs/api-guide.md.
 * Optional per-channel notes: docs/api-notes/channels.json ({ "channel": "note" }).
 * JSDoc immediately above this.handle(...) is preferred for new handlers.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const CHANNELS_PATH = path.join(ROOT, "src/main/ipc/channels.ts");
const OUT_PATH = path.join(ROOT, "docs/api.md");
const NOTES_PATH = path.join(ROOT, "docs/api-notes/channels.json");

const SCAN_GLOBS = [
  "src/main/ipc/controllers",
  "src/main/ipc/handlers",
  "src/main/services/updater-service.ts",
];

const BANNER = `<!-- DO NOT EDIT: generated by \`npm run docs:api\` (scripts/generate-api-docs.mjs). -->
<!-- Narrative guide / examples: docs/api-guide.md. Channel notes: docs/api-notes/channels.json or JSDoc above this.handle(...). -->

# API Documentation (IPC Reference)

> **Generated** from \`src/main/ipc/channels.ts\` and handler registrations.
> For usage patterns (React Query, security narrative, bridge overview), see [API Guide](./api-guide.md).

`;

/**
 * @param {string} filePath
 * @returns {string}
 */
function readUtf8(filePath) {
  return fs.readFileSync(filePath, "utf8");
}

/**
 * Flatten IPC_CHANNELS nested object into Map<"GROUP.KEY", channelString>
 * and Map<channelString, "GROUP.KEY">.
 * @param {string} source
 */
function parseChannels(source) {
  const byToken = new Map();
  const byChannel = new Map();

  const bodyMatch = source.match(
    /export const IPC_CHANNELS\s*=\s*\{([\s\S]*)\}\s*as const/
  );
  if (!bodyMatch) {
    throw new Error("Could not parse IPC_CHANNELS object from channels.ts");
  }

  let group = null;
  for (const rawLine of bodyMatch[1].split("\n")) {
    const line = rawLine.trim();
    const groupOpen = line.match(/^([A-Z][A-Z0-9_]*)\s*:\s*\{/);
    if (groupOpen) {
      group = groupOpen[1];
      continue;
    }
    if (line === "}," || line === "}") {
      if (line === "},") {
        group = null;
      }
      continue;
    }
    if (!group) {
      continue;
    }
    const entry = line.match(
      /^([A-Z][A-Z0-9_]*)\s*:\s*"([^"]+)"(?:\s*as const)?\s*,?/
    );
    if (!entry) {
      continue;
    }
    const token = `${group}.${entry[1]}`;
    const channel = entry[2];
    byToken.set(token, channel);
    if (!byChannel.has(channel)) {
      byChannel.set(channel, token);
    }
  }

  return { byToken, byChannel };
}

/**
 * @param {string} dirOrFile
 * @returns {string[]}
 */
function collectTsFiles(dirOrFile) {
  const absolute = path.join(ROOT, dirOrFile);
  if (!fs.existsSync(absolute)) {
    return [];
  }
  const stat = fs.statSync(absolute);
  if (stat.isFile()) {
    return absolute.endsWith(".ts") ? [absolute] : [];
  }
  /** @type {string[]} */
  const files = [];
  for (const name of fs.readdirSync(absolute).sort()) {
    const full = path.join(absolute, name);
    if (fs.statSync(full).isDirectory()) {
      files.push(...collectTsFiles(path.relative(ROOT, full)));
    } else if (name.endsWith(".ts") && !name.endsWith(".d.ts")) {
      files.push(full);
    }
  }
  return files;
}

/**
 * Collapse schema source to a short single-line summary.
 * @param {string} fileSource
 * @param {string} schemaExpr
 */
function summarizeSchema(fileSource, schemaExpr) {
  const trimmed = schemaExpr.replace(/\s+/g, " ").trim();
  if (trimmed === "z.tuple([])") {
    return "`[]` (no args)";
  }
  if (trimmed.startsWith("z.")) {
    const short =
      trimmed.length > 120 ? `${trimmed.slice(0, 117)}...` : trimmed;
    return `\`${short}\``;
  }

  const name = trimmed;
  const decl = new RegExp(
    `(?:const|let|type)\\s+${name}\\s*=\\s*([\\s\\S]*?);`,
    "m"
  );
  const match = fileSource.match(decl);
  if (!match) {
    return `schema: see source (\`${name}\`)`;
  }
  const body = match[1].replace(/\s+/g, " ").trim();
  const short = body.length > 120 ? `${body.slice(0, 117)}...` : body;
  return `\`${short}\``;
}

/**
 * JSDoc immediately preceding index in source.
 * @param {string} source
 * @param {number} index
 */
function extractJsDoc(source, index) {
  const before = source.slice(0, index);
  const match = before.match(/\/\*\*([\s\S]*?)\*\/\s*$/);
  if (!match) {
    return "";
  }
  return match[1]
    .split("\n")
    .map((line) => line.replace(/^\s*\*\s?/, "").trim())
    .filter((line) => line.length > 0 && !line.startsWith("@"))
    .join(" ")
    .trim();
}

/**
 * @typedef {{
 *   channel: string,
 *   token: string | null,
 *   schema: string,
 *   idempotent: boolean,
 *   controller: string,
 *   description: string,
 *   sourceFile: string,
 * }} HandlerRow
 */

/**
 * @param {string} filePath
 * @param {Map<string, string>} byToken
 * @returns {HandlerRow[]}
 */
function extractHandlersFromFile(filePath, byToken) {
  const source = readUtf8(filePath);
  const rel = path.relative(ROOT, filePath).replace(/\\/g, "/");
  const controller = path.basename(filePath, ".ts");
  /** @type {HandlerRow[]} */
  const rows = [];

  const handleRe =
    /(?:this|ipcMain)\.handle\(\s*((?:IPC_CHANNELS\.[A-Z0-9_]+\.[A-Z0-9_]+)|"[^"]+")\s*,\s*/g;

  let match;
  while ((match = handleRe.exec(source)) !== null) {
    const channelExpr = match[1];
    const callStart = match.index;
    let channel;
    let token = null;

    if (channelExpr.startsWith('"')) {
      channel = channelExpr.slice(1, -1);
    } else {
      token = channelExpr.replace(/^IPC_CHANNELS\./, "");
      channel = byToken.get(token);
      if (!channel) {
        continue;
      }
    }

    const afterComma = source.slice(match.index + match[0].length);
    let schemaExpr = "unknown";
    // Raw ipcMain.handle(channel, async () => ...) — no Zod args schema
    if (/^(?:async\s*)?\(/.test(afterComma)) {
      schemaExpr = "z.tuple([])";
    } else {
      const schemaIdent = afterComma.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*,/);
      const schemaZod = afterComma.match(
        /^(z\.[\s\S]*?)\s*,\s*(?:\(|this\.|async\s|\()/
      );
      const schemaZodTuple = afterComma.match(/^(z\.tuple\(\[[\s\S]*?\]\))\s*,/);

      if (schemaZodTuple) {
        schemaExpr = schemaZodTuple[1].replace(/\s+/g, " ");
      } else if (schemaIdent) {
        schemaExpr = schemaIdent[1];
      } else if (schemaZod) {
        schemaExpr = schemaZod[1].replace(/\s+/g, " ");
      }
    }

    // Look ahead for options object on this handle call (bounded window)
    const window = source.slice(callStart, callStart + 800);
    const idempotent = /isIdempotent\s*:\s*true/.test(window);

    const jsdoc = extractJsDoc(source, callStart);
    const schemaSummary = summarizeSchema(source, schemaExpr);

    rows.push({
      channel,
      token,
      schema: schemaSummary,
      idempotent,
      controller,
      description: jsdoc,
      sourceFile: rel,
    });
  }

  return rows;
}

/**
 * @returns {Record<string, string>}
 */
function loadChannelNotes() {
  if (!fs.existsSync(NOTES_PATH)) {
    return {};
  }
  const raw = JSON.parse(readUtf8(NOTES_PATH));
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new Error("docs/api-notes/channels.json must be a JSON object");
  }
  /** @type {Record<string, string>} */
  const notes = {};
  for (const [key, value] of Object.entries(raw)) {
    if (typeof value === "string") {
      notes[key] = value;
    }
  }
  return notes;
}

/**
 * @param {HandlerRow[]} handlers
 * @param {Map<string, string>} byChannel
 * @param {Record<string, string>} notes
 */
function renderMarkdown(handlers, byChannel, notes) {
  const byChannelHandlers = new Map();
  for (const row of handlers) {
    const list = byChannelHandlers.get(row.channel) ?? [];
    list.push(row);
    byChannelHandlers.set(row.channel, list);
  }

  const allChannels = [...byChannel.keys()].sort((a, b) => a.localeCompare(b));

  /** @type {string[]} */
  const lines = [BANNER];
  lines.push("## Channel index");
  lines.push("");
  lines.push(
    "| Channel | Token | Args (Zod) | Idempotent | Handler | Notes |"
  );
  lines.push("| --- | --- | --- | --- | --- | --- |");

  for (const channel of allChannels) {
    const token = byChannel.get(channel) ?? "";
    const regs = byChannelHandlers.get(channel) ?? [];
    if (regs.length === 0) {
      const note =
        notes[channel] ??
        "_No `handle` registration found (event channel or registered outside scanned paths)._";
      lines.push(
        `| \`${channel}\` | \`${token}\` | — | — | — | ${escapeCell(note)} |`
      );
      continue;
    }

    for (const row of regs) {
      const noteParts = [];
      if (row.description) {
        noteParts.push(row.description);
      }
      if (notes[channel]) {
        noteParts.push(notes[channel]);
      }
      if (noteParts.length === 0) {
        noteParts.push(`\`${row.sourceFile}\``);
      }
      lines.push(
        `| \`${channel}\` | \`${row.token ?? token}\` | ${escapeCell(row.schema)} | ${row.idempotent ? "yes" : "no"} | \`${row.controller}\` | ${escapeCell(noteParts.join(" — "))} |`
      );
    }
  }

  lines.push("");
  lines.push("## Coverage");
  lines.push("");
  const registered = allChannels.filter((c) => byChannelHandlers.has(c)).length;
  lines.push(
    `- Channels in \`channels.ts\`: **${allChannels.length}**`
  );
  lines.push(
    `- Channels with at least one scanned \`handle\` registration: **${registered}**`
  );
  lines.push(
    `- Handler rows extracted: **${handlers.length}**`
  );
  lines.push("");
  lines.push("## Regenerating");
  lines.push("");
  lines.push("```bash");
  lines.push("npm run docs:api");
  lines.push("```");
  lines.push("");
  lines.push(
    "CI fails if this file is stale (`npm run docs:api` then `git diff --exit-code docs/api.md`)."
  );
  lines.push("");

  return lines.join("\n");
}

/**
 * @param {string} text
 */
function escapeCell(text) {
  return text.replace(/\|/g, "\\|").replace(/\n/g, " ");
}

function main() {
  const channelsSource = readUtf8(CHANNELS_PATH);
  const { byToken, byChannel } = parseChannels(channelsSource);

  /** @type {string[]} */
  const files = [];
  for (const glob of SCAN_GLOBS) {
    files.push(...collectTsFiles(glob));
  }
  files.sort();

  /** @type {HandlerRow[]} */
  const handlers = [];
  for (const file of files) {
    handlers.push(...extractHandlersFromFile(file, byToken));
  }
  handlers.sort((a, b) => {
    const c = a.channel.localeCompare(b.channel);
    if (c !== 0) {
      return c;
    }
    return a.controller.localeCompare(b.controller);
  });

  const notes = loadChannelNotes();
  const markdown = renderMarkdown(handlers, byChannel, notes);
  fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });
  fs.writeFileSync(OUT_PATH, markdown, "utf8");
  process.stdout.write(
    `Wrote ${path.relative(ROOT, OUT_PATH)} (${byChannel.size} channels, ${handlers.length} handlers)\n`
  );
}

main();
